// Draws the atmosphere of a cloud tier / garden zone by rank (systems/animation/rankAtmosphere.ts): a soft vignette, shafts of light,
// a warm bloom over the plots, twinkling sparkles, falling petals / leaves and fireflies. Everything is generated by code (no files),
// tinted by the skin's mood, and it works without WebGL; reduced motion freezes it at a calm still frame.
import * as Phaser from 'phaser';
import { atmosphereFor, ATMOSPHERE_MAX, breathe, effectsScale, particleCountsFor, PLAIN_COLOURS, type AtmosphereColours, type EffectsMode } from '../../systems/animation/rankAtmosphere';
import { driftPose, type DriftSpec } from '../../systems/animation/rankScenery';
import { DOT, ensureSoftTextures, SOFT_GLOW } from './softTextures';
import type { SceneryTheme } from './rankScenery';

const PETAL = 'atmo_petal';
const RAY = 'atmo_ray';
const VIGNETTE = 'atmo_vignette';

function canvas(scene: Phaser.Scene, key: string, w: number, h: number, paint: (ctx: CanvasRenderingContext2D) => void) {
  if (scene.textures.exists(key)) return;
  const tex = scene.textures.createCanvas(key, w, h)!;
  paint(tex.getContext());
  tex.refresh();
}

function ensureTextures(scene: Phaser.Scene) {
  ensureSoftTextures(scene);
  canvas(scene, PETAL, 32, 32, (c) => {
    c.fillStyle = '#fff';
    c.beginPath();
    c.moveTo(16, 3);
    c.bezierCurveTo(30, 10, 28, 24, 16, 29);
    c.bezierCurveTo(4, 24, 2, 10, 16, 3);
    c.fill();
  });
  canvas(scene, RAY, 64, 256, (c) => {
    c.filter = 'blur(5px)'; // soft edges (Chromium / Electron); a hard-edged shaft where the filter is missing
    const g = c.createLinearGradient(0, 0, 0, 256);
    g.addColorStop(0, 'rgba(255,255,255,0.9)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    c.fillStyle = g;
    c.beginPath();
    c.moveTo(24, 0);
    c.lineTo(40, 0);
    c.lineTo(64, 256);
    c.lineTo(0, 256);
    c.closePath();
    c.fill();
  });
  canvas(scene, VIGNETTE, 256, 256, (c) => {
    const g = c.createRadialGradient(128, 128, 70, 128, 128, 182);
    g.addColorStop(0, 'rgba(255,255,255,0)');
    g.addColorStop(1, 'rgba(255,255,255,1)');
    c.fillStyle = g;
    c.fillRect(0, 0, 256, 256);
  });
}

const darken = (c: number, f: number): number => (Math.round(((c >> 16) & 255) * f) << 16) | (Math.round(((c >> 8) & 255) * f) << 8) | Math.round((c & 255) * f);

export interface AtmosphereDeps {
  design: { width: number; height: number };
  /** The rectangle around the plots (design px): rays and bloom gather there. */
  field: { x: number; y: number; width: number; height: number };
  /** Depth of the layer: above the plots, under the signs and the HUD. */
  depth: number;
  area: keyof typeof PLAIN_COLOURS;
}

type Img = Phaser.GameObjects.Image;

export class RankAtmosphere {
  private readonly vignette: Img;
  private readonly glow: Img;
  private readonly rays: Img[];
  private readonly sparkles: Img[];
  private readonly petals: Img[];
  private readonly fireflies: Img[];
  private rank = 1;
  private theme: SceneryTheme | null = null;
  /** Effects intensity (decision 057, B8): fewer particles and fainter rays when lighter, none when off. */
  private mode: EffectsMode = 'full';
  private colours: AtmosphereColours;
  private counts = { petals: 0, fireflies: 0 };
  private readonly fall: DriftSpec;
  private readonly wander: DriftSpec;

  constructor(scene: Phaser.Scene, private readonly d: AtmosphereDeps) {
    ensureTextures(scene);
    this.colours = PLAIN_COLOURS[d.area];
    const { width: W, height: H } = d.design;
    const f = d.field;
    const make = (key: string, depth: number, add: boolean) => {
      const img = scene.add.image(0, 0, key).setDepth(depth).setVisible(false);
      if (add) img.setBlendMode(Phaser.BlendModes.ADD);
      return img;
    };
    this.vignette = make(VIGNETTE, d.depth, false).setPosition(W / 2, H / 2).setDisplaySize(W * 1.15, H * 1.15);
    this.glow = make(SOFT_GLOW, d.depth + 1, true).setPosition(f.x + f.width / 2, f.y + f.height / 2).setDisplaySize(f.width * 1.5, f.height * 1.7);
    this.rays = Array.from({ length: ATMOSPHERE_MAX.rays }, () => make(RAY, 5, true).setOrigin(0.5, 0)); // behind the plots (depth 10)
    this.sparkles = Array.from({ length: ATMOSPHERE_MAX.sparkles }, () => make(DOT, d.depth + 3, true));
    this.petals = Array.from({ length: ATMOSPHERE_MAX.petals }, () => make(PETAL, d.depth + 4, false).setScale(0.55));
    this.fireflies = Array.from({ length: ATMOSPHERE_MAX.fireflies }, () => make(SOFT_GLOW, d.depth + 5, true).setScale(0.2));
    this.fall = { count: ATMOSPHERE_MAX.petals, x0: f.x - 40, x1: f.x + f.width + 40, y0: f.y - 130, y1: f.y + f.height + 30, periodMs: 11_000 };
    this.wander = { count: ATMOSPHERE_MAX.fireflies, x0: f.x - 20, x1: f.x + f.width + 20, y0: f.y + 10, y1: f.y + f.height + 40, periodMs: 7000 };
    this.set(1, null);
  }

  /** A new rank / skin: what shows and in which colours (`theme` null = the plain mood of the Area). */
  set(rank: number, theme: SceneryTheme | null, mode: EffectsMode = this.mode) {
    this.rank = rank;
    this.theme = theme;
    this.mode = mode;
    const a = atmosphereFor(rank, mode);
    this.colours = theme ? { light: theme.scenery, petal: theme.frame, spark: theme.frame, shade: darken(theme.frame, 0.35) } : PLAIN_COLOURS[this.d.area];
    this.counts = particleCountsFor(rank, theme?.particles ?? 'both', mode);
    const c = this.colours;
    this.vignette.setVisible(a.vignette > 0).setTint(c.shade).setAlpha(a.vignette);
    this.glow.setVisible(a.glow > 0).setTint(c.light);
    this.rays.forEach((r, i) => r.setVisible(i < a.rays).setTint(c.light));
    this.sparkles.forEach((s, i) => s.setVisible(i < a.sparkles).setTint(c.spark));
    this.petals.forEach((p, i) => p.setVisible(i < this.counts.petals).setTint(c.petal));
    this.fireflies.forEach((p, i) => p.setVisible(i < this.counts.fireflies).setTint(c.spark));
  }

  /** One frame. `mode` = the effects setting now: a change shows at once. */
  update(timeMs: number, still: boolean, mode: EffectsMode = this.mode) {
    if (mode !== this.mode) this.set(this.rank, this.theme, mode);
    const a = atmosphereFor(this.rank, this.mode);
    if (this.rank <= 1) return;
    const fx = effectsScale(this.mode);
    const calm = still || !fx.breathe; // no breathing light
    const steady = still || !fx.twinkle; // no quick twinkle
    const f = this.d.field;
    this.glow.setAlpha(a.glow * (0.75 + 0.5 * breathe(timeMs, 5200, 0, calm)));
    this.rays.forEach((r, i) => {
      if (i >= a.rays) return;
      const x = f.x + (f.width * (i + 0.5)) / a.rays;
      r.setPosition(x, -10).setRotation(((i - (a.rays - 1) / 2) * 0.16) + (still ? 0 : Math.sin(timeMs / 4300 + i) * 0.02));
      r.setDisplaySize(f.width / a.rays * 0.28, this.d.design.height * 0.5).setAlpha(a.rayAlpha * (0.6 + 0.8 * breathe(timeMs, 6400, i * 1.3, calm)));
    });
    this.sparkles.forEach((s, i) => {
      if (i >= a.sparkles) return;
      const u = (i * 0.618034) % 1;
      const v = (i * 0.381966 + 0.2) % 1;
      s.setPosition(f.x + f.width * u, f.y - 20 + (f.height + 40) * v).setScale(0.6 + (i % 3) * 0.5).setAlpha(0.15 + 0.85 * breathe(timeMs, 1700 + (i % 5) * 300, i * 2.1, steady) ** 3);
    });
    this.petals.forEach((p, i) => {
      if (i >= this.counts.petals) return;
      const q = driftPose('petal', this.fall, i, timeMs, still);
      p.setPosition(q.x, q.y).setAlpha(q.alpha * 0.9).setRotation(still ? i : timeMs / 900 + i);
    });
    this.fireflies.forEach((p, i) => {
      if (i >= this.counts.fireflies) return;
      const q = driftPose('firefly', this.wander, i, timeMs, still);
      p.setPosition(q.x, q.y).setAlpha(q.alpha);
    });
  }
}
